import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import MonitoringWidget from "../components/MonitoringWidget";
import MLWidget from "../components/MLWidget";
import LogsWidget from "../components/LogsWidget";
import api from "../services/api";
import "./AdminDashboard.css";

const AdminDashboard = () => {
  const [darkMode, setDarkMode] = useState(false);
  const [webServiceStatus, setWebServiceStatus] = useState("Checking...");
  const [dbServiceStatus, setDbServiceStatus] = useState("Checking...");
  const navigate = useNavigate();

  const handleToggleDarkMode = () => {
    setDarkMode((prev) => !prev);
    document.body.style.backgroundColor = darkMode ? "#fff" : "#1e293b";
    document.body.style.color = darkMode ? "#000" : "#fff";
  };

  const handleAutomateResolution = () => {
    alert("Automated resolution triggered!");
  };

  const handleLogout = () => {
    localStorage.removeItem("token");
    navigate("/login");
  };

  // Fetch Web & Database Service Status
  const fetchServiceStatus = async () => {
    try {
      const token = localStorage.getItem("token");
      if (!token) return;

      const response = await api.get("/api/auth/metrics/", {
        headers: { Authorization: `Token ${token}` },
      });

      if (Array.isArray(response.data) && response.data.length > 0) {
        setWebServiceStatus(String(response.data[0].web_service_status));
        setDbServiceStatus(String(response.data[0].db_service_status));
      }
    } catch (error) {
      console.error("Error fetching service status:", error);
    }
  };

  useEffect(() => {
    fetchServiceStatus();
    const interval = setInterval(fetchServiceStatus, 10000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className={`admin-dashboard ${darkMode ? "dark-mode" : "light-mode"}`}>
      <div className="navbar">
        <h1 className="dashboard-title">Admin Dashboard</h1>
        <div className="button-group">
          <button onClick={handleToggleDarkMode}>
            Toggle {darkMode ? "Light" : "Dark"} Mode
          </button>
          <button className="logout-btn" onClick={handleLogout}>Logout</button>
        </div>
      </div>

      <div className="widgets-container">
        <MonitoringWidget />
        <LogsWidget />
        <MLWidget />

        {/* ✅ Ensure Service Status is a String */}
        <div className="widget service-status-widget">
          <h3>Service Status</h3>
          <p>
            <strong>Web Service:</strong> 
            <span className={webServiceStatus === "Running" ? "status-green" : "status-red"}>
              {webServiceStatus}
            </span>
          </p>
          <p>
            <strong>Database Service:</strong> 
            <span className={dbServiceStatus === "Running" ? "status-green" : "status-red"}>
              {dbServiceStatus}
            </span>
          </p>
        </div>

        <div className="widget error-widget">
          <h3>Error Rates</h3>
          <p className="error-rate">2.5%</p>
        </div>

        <div className="widget automation-widget">
          <h3>Automated Resolution</h3>
          <button onClick={handleAutomateResolution}>Trigger Automation</button>
          <p>This will automatically resolve common server issues.</p>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
